<?php
namespace App\Http\Controllers\Api\V1;use App\Http\Requests\CreateRequestRequest;use App\Models\Request as LeadRequest;use App\Services\RequestManagementService;use Illuminate\Http\Request;
class RequestController extends ApiController{public function __construct(private RequestManagementService $service){}public function store(CreateRequestRequest $r){$u=$r->user();$data=$this->service->create($r->validated(),$u);return response()->json(['data'=>$data,'meta'=>[]],201);}public function mine(Request $r){return $this->success(LeadRequest::where('user_id',$r->user()->id)->latest()->paginate(20));}public function showMine(Request $r,LeadRequest $lead){abort_unless($lead->user_id===$r->user()->id,404);return $this->success($lead->load(['service','provider','assignments']));}}
